package com.careflow.hospital.scheduling;
import jakarta.validation.constraints.*; import java.time.*; import java.util.UUID;
public final class ScheduleDtos {private ScheduleDtos(){}public record CreateSchedule(@Min(1)@Max(7)int dayOfWeek,@NotNull LocalTime startsAt,@NotNull LocalTime endsAt,@Min(5)@Max(240)int slotDurationMinutes){}public record ScheduleView(UUID scheduleId,int dayOfWeek,LocalTime startsAt,LocalTime endsAt,int slotDurationMinutes){}public record CreateException(@NotNull @FutureOrPresent LocalDate date,@NotBlank @Pattern(regexp="UNAVAILABLE|AVAILABLE")String type,LocalTime startsAt,LocalTime endsAt,@Min(5)@Max(240)Integer slotDurationMinutes,@Size(max=300)String reason){}public record ExceptionView(UUID exceptionId,LocalDate date,String type,LocalTime startsAt,LocalTime endsAt,Integer slotDurationMinutes,String reason){}}
